        :index => enemy_count-1,
        :mode => mode,
        :qty => qty,
        :chance => enemy_data["chance"] || 1, 
        :optional => enemy_data["optional"],
        :name => enemy_data["loadout"],
        :color => '#F00',
        :location => location,
      }
    end,
    
  }
  
